static bool vdpasim_blk_check_range ( struct vdpasim * vdpasim , u64 start_sector , u64 num_sectors , u64 max_sectors ) { if ( start_sector > VDPASIM_BLK_CAPACITY ) { dev_dbg ( & vdpasim -> vdpa . dev , "starting sector exceeds the capacity - start: 0x%llx capacity: 0x%x\n" , start_sector , VDPASIM_BLK_CAPACITY ) ; } if ( num_sectors > VDPASIM_BLK_CAPACITY - start_sector ) { dev_dbg ( & vdpasim -> vdpa . dev , "request exceeds the capacity - start: 0x%llx num: 0x%llx capacity: 0x%x\n" , start_sector , num_sectors , VDPASIM_BLK_CAPACITY ) ; return false ; } return true ; } 